import java.util.Objects;
public final class WindowCounts {
    private WindowCounts() {}
    public static int countAtLeast(int[] values, int from, int to, int threshold) {
        Objects.requireNonNull(values, "values");
        if (from < 0 || to > values.length || from > to) throw new IllegalArgumentException("Invalid window");
        int count = 0;
        for (int i = from; i < to; i++) if (values[i] >= threshold) count++;
        return count;
    }
}
